"use client"

import * as React from "react"
import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox"
import { Check, Minus } from "lucide-react"

import { cn } from "@/lib/utils"

/* Checked state reuses the primary Button's neon material, scaled down. */
const Checkbox = React.forwardRef<
  HTMLButtonElement,
  Omit<CheckboxPrimitive.Root.Props, "className"> & { className?: string }
>(({ className, ...props }, ref) => (
  <CheckboxPrimitive.Root
    data-slot="checkbox"
    ref={ref}
    nativeButton
    render={<button type="button" />}
    className={cn(
      "peer h-[1.125rem] w-[1.125rem] shrink-0 rounded-[0.375rem] border border-border",
      "flex items-center justify-center",
      "bg-input [box-shadow:inset_0_0.0625rem_0.125rem_oklch(0_0_0_/_0.4)]",
      "transition-[background,box-shadow,border-color] duration-fast",
      "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
      "disabled:cursor-not-allowed disabled:opacity-50",
      "data-checked:[background:var(--neon-gradient)] data-checked:text-primary-foreground data-checked:border-transparent data-checked:[box-shadow:var(--shadow-neon)]",
      "data-indeterminate:[background:var(--neon-gradient)] data-indeterminate:text-primary-foreground data-indeterminate:border-transparent data-indeterminate:[box-shadow:var(--shadow-neon)]",
      className
    )}
    {...props}
  >
    <CheckboxPrimitive.Indicator data-slot="checkbox-indicator" className="size-full flex items-center justify-center text-current">
      {props.indeterminate ? (
        <Minus className="h-3 w-3" strokeWidth={3} />
      ) : (
        <Check className="h-3 w-3" strokeWidth={3} />
      )}
    </CheckboxPrimitive.Indicator>
  </CheckboxPrimitive.Root>
))
Checkbox.displayName = "Checkbox"

export { Checkbox }
